import{_ as a,o as i,c as s,a2 as t}from"./chunks/framework.BfI5QxtK.js";const u=JSON.parse('{"title":"files_and_load_order","description":"","frontmatter":{},"headers":[],"relativePath":"guides/files_and_load_order.md","filePath":"guides/files_and_load_order.md"}'),n={name:"guides/files_and_load_order.md"};function l(d,e,o,r,h,p){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="files-and-load-order" tabindex="-1">files_and_load_order <a class="header-anchor" href="#files-and-load-order" aria-label="Permalink to &quot;files_and_load_order&quot;">​</a></h1><p><a href="/gnoblin/config/configure">Configuration reference</a></p><p>Start with one <code>init.lua</code>. Split it into modules when that makes it easier to read.</p><h2 id="which-file-is-loaded" tabindex="-1">Which file is loaded? <a class="header-anchor" href="#which-file-is-loaded" aria-label="Permalink to &quot;Which file is loaded?&quot;">​</a></h2><p><code>gnoblinctl config path</code> prints the main config file used by your running session.</p><p>The usual path is <code>~/.config/gnoblin/init.lua</code>, or <code>$XDG_CONFIG_HOME/gnoblin/init.lua</code> when that variable is set. The compositor&#39;s <code>GNOBLIN_CONFIG</code> environment variable overrides it.</p><p>For packaged logins, <code>gnoblin-session</code> copies <code>/usr/share/gnoblin/init.lua.example</code> to <code>init.lua</code> when no user config exists. The shell loads that file when its config starts.</p><p>If the example is unavailable, or you run a build directly, Gnoblin uses its defaults. Setting <code>GNOBLIN_CONFIG</code> in a terminal does not change the environment of an already-running compositor.</p><h2 id="include-a-file" tabindex="-1">Include a file <a class="header-anchor" href="#include-a-file" aria-label="Permalink to &quot;Include a file&quot;">​</a></h2><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">load</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;appearance.lua&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The path is relative to the calling file. Absolute and <code>~/</code> paths also work. The included file uses the same API:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    shell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {minimize_duration </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 150</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="include-a-directory" tabindex="-1">Include a directory <a class="header-anchor" href="#include-a-directory" aria-label="Permalink to &quot;Include a directory&quot;">​</a></h2><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">load</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;conf.d/**/*.lua&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Matching files load in filename order (byte order, independent of your language settings). Use numbered names such as <code>10-appearance.lua</code> and <code>90-local.lua</code> to make the order predictable.</p><ul><li><code>*</code>, <code>?</code> and <code>[abc]</code> match within one path segment.</li><li><code>**</code> also searches subdirectories, without following directory symlinks.</li><li>Hidden names need an explicit dot in the pattern.</li><li>An unmatched glob is allowed; a missing exact filename is an error.</li></ul><p>Files and searched directories are watched, including newly added matches.</p><h2 id="override-or-append" tabindex="-1">Override or append? <a class="header-anchor" href="#override-or-append" aria-label="Permalink to &quot;Override or append?&quot;">​</a></h2><p>Put <code>gnoblin.load(...)</code> calls before your personal settings so your changes are applied last.</p><p>Repeated <code>gnoblin.configure</code> calls keep settings you have not changed:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {shell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {minimize_animation </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fade&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, minimize_duration </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {shell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {minimize_duration </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 150</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>The result is a fade lasting 150 milliseconds. Changing the duration does not remove the animation choice.</p><p>Lists replace earlier values. This applies to <code>window_rules</code>, <code>shortcuts</code>, <code>autostart</code> and permission <code>rules</code>.</p><p>To add a window rule while keeping previous rules, use:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">window_rule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    match </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {type </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;window&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, focused </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    opacity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.95</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The <code>shortcuts</code> and <code>autostart</code> maps merge entries with the same name. Set an entry&#39;s <code>enable</code> field to <code>false</code> to disable an imported shortcut or autostart. Disabling an autostart entry does not stop a running process.</p><p>To remove every shortcut loaded so far:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {shortcuts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {}}</span></span></code></pre></div><p>Use <code>gnoblin.configure.shortcuts</code> to add or change individual shortcuts without clearing the others.</p><h2 id="use-a-lua-module" tabindex="-1">Use a Lua module <a class="header-anchor" href="#use-a-lua-module" aria-label="Permalink to &quot;Use a Lua module&quot;">​</a></h2><p>Use a module when you want a file to return settings for another file to use. For ordinary config files, <code>gnoblin.load</code> is enough.</p><p>In <code>appearance.lua</code>:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {shell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {minimize_duration </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 150</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>In <code>init.lua</code>:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;appearance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p><code>require(&quot;appearance&quot;)</code> searches <code>appearance.lua</code>, then <code>lua/appearance.lua</code>, relative to its caller. It runs once per reload.</p><p>Returning a table does not apply its settings by itself. Pass it to <code>gnoblin.configure</code> as shown above.</p><p>Dots in module names are not converted to directories. For explicit subdirectories, use <code>gnoblin.load(&quot;parts/motion.lua&quot;)</code>. Avoid loading the same file through both a glob and <code>require</code>.</p><h2 id="available-lua-functions" tabindex="-1">Available Lua functions <a class="header-anchor" href="#available-lua-functions" aria-label="Permalink to &quot;Available Lua functions&quot;">​</a></h2><p><code>gnoblin</code> is available globally in every loaded file and module. See the <a href="/gnoblin/config#api-reference">function reference</a>.</p><p>Setting names use <code>snake_case</code>. The API converts them to Gnoblin&#39;s internal hyphenated names. String values, shader uniform names and renderer names stay literal. Do not supply both spellings of the same key in one table.</p><p>Each reload evaluates the files again; Lua variables do not survive it. You can use Lua&#39;s table, string, math and UTF-8 helpers. Config code cannot read arbitrary files, run processes or load native modules. Use shortcuts or autostart to launch programs.</p><p>Evaluation is limited to 8 MiB of Lua memory, one million instructions and 32 nested files.</p><p>Lua configuration cannot run arbitrary JavaScript. For custom live automation, see <a href="/gnoblin/user-scripts">user scripts</a>; most settings and desktop behavior should stay in the supported configuration API.</p><h2 id="reload-and-persistence" tabindex="-1">Reload and persistence <a class="header-anchor" href="#reload-and-persistence" aria-label="Permalink to &quot;Reload and persistence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Change</th><th>Applies</th><th>When removed</th></tr></thead><tbody><tr><td>Rules and animations</td><td>On reload</td><td>Earlier rules/defaults apply</td></tr><tr><td>Titlebar policy</td><td>After reload and the app&#39;s next surface update</td><td>Earlier rules/defaults apply</td></tr><tr><td>Command shortcuts</td><td>On reload</td><td>Binding released; launched process stays</td></tr><tr><td>Built-in keybindings</td><td>On reload</td><td>Built-in default applies</td></tr><tr><td>Window-management preferences</td><td>On reload</td><td>Gnoblin default applies</td></tr><tr><td>Compositor interaction preferences</td><td>On reload</td><td>Gnoblin default applies</td></tr><tr><td>Input preferences</td><td>On reload</td><td>GNOME/Mutter settings apply</td></tr><tr><td>Input sources</td><td>On reload</td><td>GNOME session sources apply</td></tr><tr><td>Orientation lock</td><td>On reload</td><td>GNOME orientation setting applies</td></tr><tr><td>Cursor theme and size</td><td>On reload</td><td>Adwaita at 24 logical pixels</td></tr><tr><td>Notifications and layout popup</td><td>On reload</td><td>Saved GSettings value stays</td></tr><tr><td>Autostart</td><td>New names start on reload</td><td>Running process stays</td></tr><tr><td>Renderer services</td><td>Restart on reload</td><td>Enabled frames use native fallback</td></tr><tr><td>Protocols</td><td>Next login</td><td>Default on next login</td></tr><tr><td>Launcher focus behaviour</td><td>Next login</td><td>Default on next login</td></tr><tr><td>Drag boundary</td><td>Next drag after reload</td><td>Defaults to enabled</td></tr></tbody></table><p>An already-started autostart name uses a changed command only on the next login. If you change a setting with the CLI, a value written in your config file will replace that change on the next config reload.</p><p><code>gnoblinctl reload</code> also reloads the theme and user scripts. Neither reload command replaces native libraries or restarts your separate desktop shell.</p>`,48)])])}const k=a(n,[["render",l]]);export{u as __pageData,k as default};
